import itertools
n=9
fixed={3:1}
cols=range(n)
for perm in itertools.permutations(cols):
    ok=True
    for r,c in fixed.items():
        if perm[r]!=c:
            ok=False;break
    if not ok: continue
    # check diagonals
    for i in range(n):
        for j in range(i+1,n):
            if abs(i-j)==abs(perm[i]-perm[j]):
                ok=False;break
        if not ok: break
    if ok:
        print(perm)
        raise SystemExit
